// Bab 13 · Padang Tanpa Hujan (arc 2 "Benang Sepi"). Dibuat untuk Laga Nusantara.
"use strict";
const CERITA_BAB13 = [
  // ===== EP 1 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 1, judul: "Rumput yang Haus", tipe: "datang", area: "sabana",
    tujuan: "Seberangi gerbang timur Labuhan menuju Padang Sabana",
    teks: [
      ["narasi", "Gerbang kota tertinggal di belakangmu. Di depan, padang rumput terbentang sampai kaki langit, kuning pucat seperti kertas tua yang terlalu lama dijemur."],
      ["narasi", "Tanah di bawah kakimu retak-retak membentuk sisik. Batu-batu megalit berdiri di sana-sini, tegak dan diam, seperti penjaga yang lupa apa yang mereka jaga."],
      ["hero", "(Peta benang dari Nyonya Mei menunjuk ke sini. Simpul-simpul di sakuku berdenyut makin keras, seperti jantung yang mencium bau rumah.)"],
      ["narasi", "Angin bertiup kencang, membawa debu dan bau rumput terbakar. Tapi anehnya, angin itu tidak bersuara sama sekali. Tak ada desir, tak ada siul."],
      ["hero", "(Bahkan angin pun dibungkam di sini. Dalang itu pasti pernah lewat.)"],
    ],
    hadiah: { exp: 5000, gold: 200 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Thirsty Grass", tujuan: "Pass through Labuhan's east gate to the Savanna Plains",
      teks: [
        "The town gate falls behind you. Ahead, grassland stretches to the horizon, pale yellow like old paper left too long in the sun.",
        "The ground under your feet is cracked into scales. Megaliths stand here and there, upright and silent, like guards who've forgotten what they were guarding.",
        "(Madam Mei's thread map points here. The knots in my pocket pulse harder, like a heart catching the scent of home.)",
        "The wind blows hard, carrying dust and the smell of scorched grass. Yet strangely, the wind makes no sound at all. No rustle, no whistle.",
        "(Even the wind is muzzled here. That Puppeteer must have come this way.)",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 1, judul: "Rumput yang Haus", tipe: "kill", target: "kalajengking", need: 7,
    tujuan: "Kalahkan 7 Kalajengking Sabana",
    teks: [
      ["narasi", "Kalajengking ketujuh menggulung ekornya, lalu diam. Cangkangnya sepanas batu bara, seolah tanah sendiri sudah terlalu panas untuk ditinggali."],
      ["hero", "(Mereka keluar dari lubang karena tanahnya kepanasan. Kasihan juga, sebenarnya. Tapi sengatannya tetap sakit sekali.)"],
      ["narasi", "Di ekor salah satunya tersangkut seutas benang hitam, tipis seperti rambut. Saat kau menyentuhnya, benang itu terasa dingin, dingin yang salah di tengah padang sepanas ini."],
      ["narasi", "Jauh di timur, asap tipis naik dari balik deretan atap tinggi beratap ilalang. Sebuah kampung. Mungkin di sana ada yang tahu kenapa padang ini kehausan."],
    ],
    hadiah: { exp: 5200, gold: 220 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Thirsty Grass", tujuan: "Defeat 7 Savanna Scorpions",
      teks: [
        "The seventh scorpion curls its tail, then lies still. Its shell is hot as coal, as if the ground itself has grown too hot to live in.",
        "(They crawled out of their holes because the earth is too hot. I feel a bit sorry for them, honestly. The sting still hurts like crazy, though.)",
        "A black thread, thin as a hair, is caught on one of their tails. When you touch it, it feels cold, a wrong kind of cold in the middle of such a scorching plain.",
        "Far to the east, thin smoke rises from behind a row of tall thatched roofs. A village. Maybe someone there knows why this plain is so thirsty.",
      ] } },

  // ===== EP 2 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 2, judul: "Kampung Megalit", tipe: "datang", area: "kampungBatu",
    tujuan: "Temukan kampung di timur Padang Sabana",
    teks: [
      ["narasi", "Kampung Megalit berdiri di atas bukit kecil. Rumah-rumahnya bertiang tinggi, atapnya menjulang runcing seperti tangan yang ditangkupkan untuk berdoa."],
      ["narasi", "Di tengah kampung berjajar kubur batu besar, dipahat dengan gambar kerbau, kuda, dan matahari. Anak-anak duduk di atasnya, menatap langit yang tak kunjung berawan."],
      ["narasi", "Dari kolong sebuah rumah terdengar bunyi alat tenun: tak, tak, tak. Satu-satunya bunyi yang terdengar sejak kau meninggalkan kota."],
      ["narasi", "Seorang nenek berambut putih mengangkat kepala dari tenunannya, lalu melambaikan tangan padamu, seolah sudah lama menunggu."],
    ],
    hadiah: { exp: 5200, gold: 200 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Megalith Village", tujuan: "Find the village east of the Savanna Plains",
      teks: [
        "Megalith Village sits atop a small hill. Its houses stand on tall stilts, their roofs soaring to a point like hands pressed together in prayer.",
        "In the middle of the village lies a row of great stone tombs, carved with buffalo, horses, and suns. Children sit on them, staring at a sky that never clouds over.",
        "From beneath one house comes the sound of a loom: tak, tak, tak. The only sound you've heard since leaving the city.",
        "A white-haired grandmother looks up from her weaving, then waves at you, as if she'd been waiting a long time.",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 2, judul: "Kampung Megalit", tipe: "bicara", npc: "inaSeli",
    tujuan: "Bicara dengan Ina Seli, penenun tua Kampung Megalit",
    teks: [
      ["inaSeli", "Duduklah, Nak, duduk. Kakimu berdebu dari ujung ke ujung. Orang yang berjalan sejauh itu di padang kering pasti membawa pertanyaan, bukan dagangan."],
      ["hero", "Aku pengembara dari Wanasari, Ina. Aku mengikuti benang hitam ini. Ia menuntunku dari seberang laut sampai ke padang Ina."],
      ["inaSeli", "Hm. Coba Ina pegang. ...Dingin. Ini bukan benang tenunan tangan manusia, Nak. Benang biasa menyimpan hangat tangan penenunnya. Benang ini tidak menyimpan apa-apa."],
      ["inaSeli", "Sudah empat puluh hari hujan tidak turun di sini. Kau tahu kenapa? Karena tugu-tugu di lembah utara berhenti bernyanyi."],
      ["inaSeli", "Tugu-tugu itu dipancangkan leluhur kami. Tubuhnya berlubang-lubang. Kalau angin lewat, mereka bersenandung, dan senandung itu memanggil awan dari laut. Begitulah hujan datang ke padang ini, turun-temurun."],
      ["inaSeli", "Empat puluh satu malam lalu, seorang lelaki bertopeng lewat kampung ini membawa peti kayu panjang. Ia tidak bicara sepatah kata pun. Ia hanya menunjuk tenunanku, lalu menulis di tanah: 'Kain tanpa motif.'"],
      ["inaSeli", "Kain tanpa motif, Nak. Kain tanpa cerita. Aku menolak. Paginya, tugu-tugu itu diam. Dan sejak itu angin pun ikut bisu."],
      ["inaSeli", "Lalu ada lagi yang lebih menyedihkan. Kuda penjaga kawanan kami, kuda bersayap yang oleh orang-orang tua disebut Sembrani, kini terbang hitam legam. Ia menyerang kawanan yang dulu ia lindungi."],
      ["hero", "Kuda bersayap... seperti dalam dongeng-dongeng lama?"],
      ["inaSeli", "Dongeng lahir dari sesuatu yang pernah dilihat orang, Nak. Pergilah ke Ama Doko, penggembala di ujung kampung. Kawanannya yang paling menderita. Dia keras kepala, tapi hatinya selembut kapas."],
    ],
    hadiah: { exp: 5500, gold: 250 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Megalith Village", tujuan: "Talk to Ina Seli, the old weaver of Megalith Village",
      teks: [
        "Sit down, child, sit. Your feet are dusty from end to end. Anyone who walks that far across a dry plain carries questions, not wares.",
        "I'm a wanderer from Wanasari, Ina. I've been following this black thread. It led me across the sea all the way to your plain.",
        "Hm. Let me hold it. ...Cold. This isn't thread spun by human hands, child. Ordinary thread keeps the warmth of the weaver's hands. This one keeps nothing.",
        "It hasn't rained here in forty days. Do you know why? Because the pillars in the northern valley have stopped singing.",
        "Our ancestors raised those pillars. Their bodies are full of holes. When the wind passes through, they hum, and that hum calls the clouds in from the sea. That's how rain comes to this plain, generation after generation.",
        "Forty-one nights ago, a masked man passed through this village carrying a long wooden chest. He didn't say a single word. He only pointed at my weaving, then wrote in the dirt: 'Cloth without a pattern.'",
        "Cloth without a pattern, child. Cloth without a story. I refused. By morning, the pillars had gone quiet. And ever since, even the wind has been mute.",
        "And there's something sadder still. The guardian horse of our herds, the winged horse the old folk call Sembrani, now flies pitch black. It attacks the very herds it once protected.",
        "A winged horse... like in the old folktales?",
        "Folktales are born from things people once saw, child. Go to Ama Doko, the herder at the edge of the village. His herd has suffered most. He's stubborn, but his heart is soft as cotton.",
      ] } },

  // ===== EP 3 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 3, judul: "Kerbau di Kubangan", tipe: "bicara", npc: "amaDoko",
    tujuan: "Temui Ama Doko, penggembala kerbau",
    teks: [
      ["amaDoko", "Kau orang yang dikirim Ina Seli? Hmph. Badanmu kecil. Kerbauku saja lebih lebar dari bahumu."],
      ["hero", "Tapi aku sudah menyeberangi lautan dan mengalahkan beberapa raja, Ama. Mungkin aku bisa membantu."],
      ["amaDoko", "...Raja, katamu. Baiklah, baiklah. Dengar. Semalam kuda hitam itu menukik ke kandang. Kawananku lari tunggang-langgang ke barat, ke arah kubangan."],
      ["amaDoko", "Sebagian sudah pulang sendiri. Tapi Si Belang, kerbau tertuaku, belum. Dia pasti terperosok di lumpur kubangan. Kubangan itu sudah hampir kering, tinggal lumpur kental yang menelan kaki."],
      ["amaDoko", "Orang kampung melarangku pergi sendiri. Katanya kalajengking di mana-mana, kerbau liar juga mengamuk. Mereka pikir aku sudah tua!"],
      ["amaDoko", "...Ya, memang aku sudah tua. Lututku bunyi kalau naik tangga. Tapi Si Belang sudah bersamaku sejak Lewa masih belajar jalan. Kerbau itu bukan harta, Nak. Dia keluarga."],
      ["amaDoko", "Jadi antar aku ke kubangan. Kau jaga kiri-kanan, aku tunjukkan jalan. Dan jangan kasihani aku. Aku paling benci dikasihani."],
    ],
    hadiah: { exp: 5400, gold: 220 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Buffalo in the Wallow", tujuan: "Meet Ama Doko, the buffalo herder",
      teks: [
        "You're the one Ina Seli sent? Hmph. You're small. My buffalo are wider than your shoulders.",
        "But I've crossed the sea and defeated a few kings, Ama. Maybe I can help.",
        "...Kings, you say. Fine, fine. Listen. Last night that black horse dove at the pen. My herd scattered west, toward the wallow.",
        "Some came home on their own. But Spotty, my oldest buffalo, hasn't. She must be stuck in the wallow mud. It's nearly dry now, just thick mud that swallows your legs.",
        "The villagers won't let me go alone. They say there are scorpions everywhere, and wild buffalo on the rampage. They think I'm old!",
        "...Well, I am old. My knees creak on the stairs. But Spotty's been with me since Lewa was learning to walk. Buffalo aren't wealth, child. They're family.",
        "So escort me to the wallow. You watch left and right, I'll show the way. And don't pity me. I hate being pitied most of all.",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 3, judul: "Kerbau di Kubangan", tipe: "kawal", npc: "amaDoko", area: "sabana",
    mulai: [56, 25], ke: [30, 27],
    sergap: [{ di: [44, 23], monster: "kerbauAmuk", jumlah: 2 }, { di: [36, 25], monster: "kalajengking", jumlah: 3 }],
    ajak: ["Jalanku memang pelan, tapi pasti. Kubangan ada di barat. Ayo, sebelum matahari makin galak.", "I walk slow, but sure. The wallow's to the west. Come on, before the sun gets any meaner."],
    gagal: ["Aduh... kakiku... Kita mundur dulu, Nak. Si Belang keras kepala, dia bisa menunggu sebentar lagi.", "Ugh... my leg... Let's fall back, child. Spotty's stubborn, she can wait a little longer."],
    tujuan: "Kawal Ama Doko ke kubangan di barat Padang Sabana",
    teks: [
      ["narasi", "Kubangan itu tinggal cekungan lumpur cokelat yang retak di pinggirnya. Di tengahnya, seekor kerbau tua berbelang putih terbenam sampai perut, melenguh lemah."],
      ["amaDoko", "Belang! Belang, ini aku! Sudah kubilang jangan lari kalau ada yang menakutkan. Lari ke aku, bukan ke lumpur, dasar kerbau bodoh kesayangan."],
      ["narasi", "Kerbau itu mengangkat kepala dan menjilat tangan Ama Doko. Lelaki tua itu buru-buru mengusap matanya dengan lengan baju, lalu berdeham keras."],
      ["amaDoko", "Debu. Itu debu. ...Tunggu. Lihat ke sana, Nak. Kerbau-kerbau liar itu. Mata mereka merah, dan ada benang hitam melilit tanduknya."],
      ["amaDoko", "Mereka tidak akan membiarkan kita menarik Belang keluar. Usir mereka. Jangan sakiti lebih dari perlu, mereka cuma ketakutan seperti kita."],
    ],
    hadiah: { exp: 6000, gold: 300, potion: 2 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Buffalo in the Wallow", tujuan: "Escort Ama Doko to the wallow in the western Savanna",
      teks: [
        "The wallow is just a hollow of brown mud, cracked at the edges. In the middle, an old white-spotted buffalo is sunk up to her belly, lowing weakly.",
        "Spotty! Spotty, it's me! I told you not to run when something scares you. Run to me, not into the mud, you silly, precious buffalo.",
        "The buffalo lifts her head and licks Ama Doko's hand. The old man hastily wipes his eyes with his sleeve, then clears his throat loudly.",
        "Dust. That's dust. ...Wait. Look over there, child. Those wild buffalo. Their eyes are red, and there's black thread wound around their horns.",
        "They won't let us pull Spotty out. Drive them off. Don't hurt them more than you must, they're only frightened, like us.",
      ] } },

  // ===== EP 4 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 4, judul: "Kawanan Mengamuk", tipe: "kill", target: "kerbauAmuk", need: 6,
    tujuan: "Tenangkan 6 Kerbau Amuk di sekitar kubangan",
    teks: [
      ["narasi", "Kerbau amuk terakhir terhuyung, dan benang hitam di tanduknya putus dengan bunyi seperti senar kecapi yang terlalu kencang. Matanya kembali cokelat, bingung, lalu ia berjalan pergi dengan tenang."],
      ["narasi", "Bersama-sama, kau dan Ama Doko menarik Si Belang dari lumpur. Butuh tiga tarikan, dua umpatan dari Ama Doko, dan satu sepatu yang hilang selamanya di dasar kubangan."],
      ["amaDoko", "Ha! Keluar juga kau, gendut! ...Nak, benang di tanduk mereka sama dengan benang di sayap kuda hitam itu. Aku melihatnya dari dekat semalam."],
      ["amaDoko", "Pulanglah duluan ke kampung. Aku akan menuntun Belang pelan-pelan. Nanti kita bicara. Ada... ada yang ingin kutanyakan padamu."],
    ],
    hadiah: { exp: 6000, gold: 280 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Raging Herd", tujuan: "Calm 6 Raging Buffalo around the wallow",
      teks: [
        "The last raging buffalo staggers, and the black thread on its horns snaps with a sound like an over-tightened lute string. Its eyes turn brown again, confused, and it ambles calmly away.",
        "Together, you and Ama Doko haul Spotty out of the mud. It takes three pulls, two curses from Ama Doko, and one sandal lost forever at the bottom of the wallow.",
        "Ha! Out you come, fatso! ...Child, the thread on their horns is the same as the thread on that black horse's wings. I saw it up close last night.",
        "Go back to the village first. I'll lead Spotty home slowly. We'll talk later. There's... something I want to ask you.",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 4, judul: "Kawanan Mengamuk", tipe: "bicara", npc: "amaDoko",
    tujuan: "Kembali ke Kampung Megalit dan temui Ama Doko",
    teks: [
      ["amaDoko", "Belang sudah di kandang, makan rumput kering sambil cemberut. Terima kasih, Nak. Ambil jagung titi ini. Jangan menolak, nanti aku tersinggung."],
      ["amaDoko", "Nah, sekarang yang ingin kutanyakan... Kau lihat anak perempuanku? Lewa. Rambutnya dikuncir, mulutnya tidak bisa diam, dan dia selalu menunggang kuda cokelat bernama Angin."],
      ["hero", "Belum, Ama. Aku belum bertemu siapa pun selain Ina Seli dan Ama."],
      ["narasi", "Ama Doko terdiam. Ia masuk ke kolong rumah, lalu keluar lagi membawa selembar daun lontar. Tangannya gemetar."],
      ["amaDoko", "Ini terselip di tiang pintu. Tulisannya: 'Ayah, aku pergi mengejar kuda hitam. Jangan marah. Aku bawa bekal. Lewa.' ...Jangan marah, katanya! Anak itu!"],
      ["amaDoko", "Ibunya dulu penunggang terbaik di sabana ini. Suatu musim hujan, dia pergi mencari anak kerbau yang hilang di tengah badai... dan tidak pernah pulang. Lewa persis ibunya. Terlalu berani, terlalu cepat."],
      ["amaDoko", "Aku tidak bisa kehilangan mereka berdua, Nak. Tidak bisa."],
      ["amaDoko", "Kuda Angin punya tapal dengan paku tiga. Jejaknya mudah dikenali. Tadi kulihat jejak itu di timur kubangan. Tolong ikuti. Tolong bawa anakku pulang."],
    ],
    hadiah: { exp: 5800, gold: 250, potion: 1 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Raging Herd", tujuan: "Return to Megalith Village and see Ama Doko",
      teks: [
        "Spotty's back in the pen, eating dry grass and sulking. Thank you, child. Take this popped corn. Don't refuse, or I'll be offended.",
        "Now, what I wanted to ask... Have you seen my daughter? Lewa. Ponytail, a mouth that never stops, and she always rides a brown horse named Wind.",
        "Not yet, Ama. I haven't met anyone besides Ina Seli and you.",
        "Ama Doko falls silent. He goes under the house, then comes back holding a palm-leaf note. His hands are shaking.",
        "This was tucked in the doorpost. It says: 'Father, I've gone after the black horse. Don't be angry. I packed food. Lewa.' ...Don't be angry, she says! That girl!",
        "Her mother was the finest rider on this savanna. One rainy season, she went looking for a lost calf in the middle of a storm... and never came home. Lewa's just like her. Too brave, too fast.",
        "I can't lose them both, child. I can't.",
        "Wind's horseshoes have three nails. Her tracks are easy to spot. I saw them east of the wallow earlier. Please follow them. Please bring my daughter home.",
      ] } },

  // ===== EP 5 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 5, judul: "Jejak Tapal", tipe: "jejak", area: "sabana",
    titik: [[40, 30], [44, 36], [48, 40], [52, 42], [55, 38]],
    tujuan: "Ikuti jejak tapal kuda Angin di Padang Sabana",
    teks: [
      ["narasi", "Jejak tapal berpaku tiga itu berlari kencang ke tenggara. Di sampingnya ada jejak lain, jauh lebih besar, dan di antara keduanya berserakan bulu-bulu hitam sepanjang lengan."],
      ["narasi", "Bulu itu bukan bulu burung. Ujungnya masih menyimpan sedikit warna emas, seperti sisa senja yang belum mau padam."],
      ["narasi", "Jejak itu berakhir di balik gugusan batu. Seekor kuda cokelat berdiri tegak di sana, telinganya tegak, menjaga seseorang yang duduk bersandar di batu."],
      ["narasi", "Kuda itu meringkik keras saat melihatmu. Lalu sebuah suara cempreng menyahut dari balik batu: 'Angin, diam! Kalau itu Ayah, bilang aku tidak ada!'"],
    ],
    hadiah: { exp: 6000, gold: 260 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Hoofprints", tujuan: "Follow Wind's hoofprints across the Savanna",
      teks: [
        "The three-nailed hoofprints race southeast. Beside them runs another set, far larger, and between the two lie scattered black feathers as long as an arm.",
        "They aren't bird feathers. Their tips still hold a hint of gold, like the last of a sunset that refuses to fade.",
        "The trail ends behind a cluster of rocks. A brown horse stands guard there, ears pricked, watching over someone sitting against the stone.",
        "The horse neighs loudly when it sees you. Then a shrill voice answers from behind the rock: 'Wind, hush! If that's Father, tell him I'm not here!'",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 5, judul: "Jejak Tapal", tipe: "bicara", npc: "lewa",
    tujuan: "Bicara dengan gadis di balik batu",
    teks: [
      ["lewa", "Oh. Bukan Ayah. Fiuh! Kau siapa? Orang kota? Sepatumu terlalu bersih untuk orang sabana. Eh, tidak juga, ternyata. Ada lumpur kubangan di situ."],
      ["hero", "Kau pasti Lewa. Ayahmu menyuruhku mencarimu. Dia khawatir setengah mati."],
      ["lewa", "Aduh. Dia marah? Jangan jawab. Pasti marah. ...Kakiku terkilir waktu jatuh. Kuda hitam itu menyambar tali lemparanku, dan aku ikut terbang sebentar. Sebentar saja. Lalu jatuh. Lama."],
      ["lewa", "Dengar, ini penting. Kuda hitam itu bukan monster. Dia Sembrani, pelindung kawanan kami. Di dongeng-dongeng lama Jawa dan negeri-negeri lain, Sembrani itu kuda bersayap yang terbang di atas awan, tunggangan para ksatria."],
      ["lewa", "Di sini, kata Ibu, Sembrani turun tiap fajar untuk menghitung kawanan. Kalau ada anak kerbau tersesat, dia yang menggiringnya pulang. Aku pernah melihatnya sekali, waktu kecil, di kubur batu Ibu. Bulunya putih, sayapnya keemasan."],
      ["lewa", "Sekarang sayapnya terlilit benang hitam. Banyak sekali, seperti jaring. Benang itu menarik-nariknya seperti... seperti wayang. Dia menyerang kawanan, tapi aku lihat matanya. Dia menangis."],
      ["hero", "Benang itu sama dengan yang kuikuti dari seberang laut. Ada seorang dalang yang memainkannya."],
      ["lewa", "Dalang? Jadi ada orang yang sengaja?! Aduh, kalau ketemu, kugigit dia. ...Oke, aku punya ide. Kuda-kuda liar di padang ini selalu mengikuti Sembrani. Surai mereka menyimpan bau langit, kata Ina Seli."],
      ["lewa", "Kalau surai itu ditenun Ina Seli jadi tali, talinya bisa menenangkan Sembrani tanpa melukainya. Kau kumpulkan surainya, ya? Angin akan membawaku pulang. Dan... tolong bilang Ayah aku baik-baik saja. Pakai kata-kata yang manis."],
    ],
    hadiah: { exp: 6200, gold: 300 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Hoofprints", tujuan: "Talk to the girl behind the rock",
      teks: [
        "Oh. Not Father. Phew! Who are you? City folk? Your boots are too clean for the savanna. Oh, never mind, they're not. There's wallow mud on them.",
        "You must be Lewa. Your father sent me to find you. He's worried half to death.",
        "Ugh. Is he angry? Don't answer. He's angry. ...I sprained my ankle when I fell. The black horse caught my lasso, and I flew along for a bit. Just a bit. Then I fell. For a long time.",
        "Listen, this is important. The black horse isn't a monster. It's Sembrani, guardian of our herds. In the old tales of Java and other lands, Sembrani is a winged horse that flies above the clouds, the mount of heroes.",
        "Here, Mother said, Sembrani came down every dawn to count the herds. If a calf got lost, it would guide it home. I saw it once, when I was little, at Mother's stone grave. White coat, golden wings.",
        "Now its wings are wrapped in black thread. So much of it, like a net. The thread jerks it around like... like a puppet. It attacks the herds, but I saw its eyes. It was crying.",
        "That thread is the same one I followed across the sea. There's a puppeteer pulling the strings.",
        "A puppeteer? So someone's doing this on purpose?! Ugh, if I find him, I'll bite him. ...Okay, I have an idea. The wild horses on this plain always follow Sembrani. Their manes carry the scent of the sky, Ina Seli says.",
        "If Ina Seli weaves that mane into a rope, it can calm Sembrani without hurting it. Will you gather the mane? Wind will carry me home. And... please tell Father I'm fine. Use sweet words.",
      ] } },

  // ===== EP 6 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 6, judul: "Tali Penenang", tipe: "kill", target: "kudaLiar", need: 6,
    tujuan: "Kalahkan 6 Kuda Liar di Padang Sabana",
    teks: [
      ["narasi", "Kuda liar keenam berhenti berlari. Ia mendengus, menggeleng-gelengkan kepala, dan seutas benang hitam halus jatuh dari surainya ke rumput."],
      ["narasi", "Benang di kuda-kuda ini jauh lebih tipis daripada di kerbau tadi. Seperti benang sisa, dibuang begitu saja setelah benang utama dipakai untuk sesuatu yang lebih besar."],
      ["hero", "(Mereka ikut terjerat hanya karena dekat dengan Sembrani. Seperti nyamuk yang terperangkap di jaring laba-laba yang dibuat untuk burung.)"],
      ["narasi", "Kuda-kuda itu kini menatapmu dengan tenang. Beberapa helai surai mereka tersangkut di semak, berkilau samar di bawah matahari."],
    ],
    hadiah: { exp: 6200, gold: 280 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Calming Rope", tujuan: "Defeat 6 Wild Horses on the Savanna",
      teks: [
        "The sixth wild horse stops running. It snorts, shakes its head, and a fine black thread drops from its mane onto the grass.",
        "The threads on these horses are much thinner than on the buffalo. Like leftover scraps, tossed aside after the main thread was used for something bigger.",
        "(They got caught only because they were near Sembrani. Like mosquitoes trapped in a spider web meant for birds.)",
        "The horses now gaze at you calmly. A few strands of their mane are caught in the bushes, shimmering faintly under the sun.",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 6, judul: "Tali Penenang", tipe: "collect", item: "suraiKuda", need: 4, dari: "kudaLiar", peluang: 0.5,
    tujuan: "Kumpulkan 4 Surai Kuda dari Kuda Liar",
    teks: [
      ["narasi", "Empat ikat surai kuda kini tergulung rapi di tasmu. Helainya halus dan panjang, dan kalau digerakkan, ada kilau keemasan yang berlari di sepanjang helainya."],
      ["narasi", "Saat kau mendekatkannya ke hidung, baunya bukan bau kuda. Baunya seperti udara sesudah hujan. Bau yang sudah empat puluh hari tidak dicium padang ini."],
      ["hero", "(Bau langit, kata Lewa. Sekarang aku mengerti maksudnya. Saatnya kembali ke Ina Seli.)"],
    ],
    hadiah: { exp: 6000, gold: 250, potion: 1 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Calming Rope", tujuan: "Gather 4 Horse Manes from Wild Horses",
      teks: [
        "Four bundles of horse mane are now neatly coiled in your bag. The strands are fine and long, and when they move, a golden shimmer runs along their length.",
        "When you hold them to your nose, they don't smell like horse. They smell like the air after rain. A smell this plain hasn't known in forty days.",
        "(The scent of the sky, Lewa said. Now I understand what she meant. Time to go back to Ina Seli.)",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 6, judul: "Tali Penenang", tipe: "bicara", npc: "inaSeli",
    tujuan: "Bawa surai kuda kepada Ina Seli",
    teks: [
      ["inaSeli", "Ah, kau membawanya. Dan wanginya... ya, ya. Wangi hujan. Kemarikan, Nak. Duduk di dekat Ina, dan jangan bicara dulu. Tenun yang baik butuh telinga yang tenang."],
      ["narasi", "Jari-jari Ina Seli yang keriput bergerak cepat, memilin surai menjadi benang, lalu benang menjadi tali. Sambil menenun, ia bersenandung pelan, lagu yang nadanya naik turun seperti bukit-bukit sabana."],
      ["inaSeli", "Kau tahu kenapa Ina bersenandung? Karena tali ini tidak boleh hanya kuat. Tali yang hanya kuat, itu tali untuk mengikat. Sembrani tidak boleh diikat. Dia harus diingatkan."],
      ["inaSeli", "Jadi ke dalam tali ini Ina tenun ceritanya. Cerita tentang kuda putih yang dulu turun dari awan, menghitung kerbau-kerbau kami, dan menggiring yang tersesat pulang. Cerita tentang siapa dia sebenarnya."],
      ["inaSeli", "Benang hitam itu membuat Sembrani lupa. Dalang itu membuatnya percaya bahwa ia hanya wayang. Tali ini akan berbisik di telinganya: 'Kau bukan wayang. Kau penjaga.'"],
      ["hero", "Ina... bagaimana dengan Lewa? Dia sudah pulang?"],
      ["inaSeli", "Hihi. Sudah. Ama Doko memarahinya sepanjang sore, lalu memeluknya sepanjang malam. Kakinya sudah Ina olesi param. Besok dia pasti sudah melompat-lompat lagi, sayangnya."],
      ["inaSeli", "Ini, tali penenangnya. Bawalah pada Lewa. Dia tahu jalan ke Bukit Sembrani lebih baik dari siapa pun di kampung ini. Dan tahu cara melempar tali... meski kemarin hasilnya agak kurang bagus."],
    ],
    hadiah: { exp: 6400, gold: 300 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Calming Rope", tujuan: "Bring the horse mane to Ina Seli",
      teks: [
        "Ah, you brought it. And the scent... yes, yes. The scent of rain. Give it here, child. Sit by me, and don't talk just yet. Good weaving needs quiet ears.",
        "Ina Seli's wrinkled fingers move swiftly, twisting the mane into thread, then the thread into rope. As she weaves, she hums softly, a tune that rises and falls like the hills of the savanna.",
        "Do you know why I hum? Because this rope mustn't only be strong. A rope that's only strong is a rope for binding. Sembrani must not be bound. It must be reminded.",
        "So into this rope I weave its story. The story of the white horse that once came down from the clouds, counted our buffalo, and guided the lost ones home. The story of who it truly is.",
        "That black thread makes Sembrani forget. The Puppeteer made it believe it's only a puppet. This rope will whisper in its ear: 'You are not a puppet. You are a guardian.'",
        "Ina... what about Lewa? Is she home?",
        "Heehee. She is. Ama Doko scolded her all afternoon, then hugged her all night. I've rubbed salve on her ankle. By tomorrow she'll be bouncing around again, unfortunately.",
        "Here's the calming rope. Take it to Lewa. She knows the way to Sembrani Hill better than anyone in this village. And how to throw a rope... though yesterday it didn't go so well.",
      ] } },

  // ===== EP 7 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 7, judul: "Bukit Sembrani", tipe: "bicara", npc: "lewa",
    tujuan: "Bawa tali penenang kepada Lewa",
    teks: [
      ["lewa", "Lihat! Lihat! Kakiku sudah bisa jinjit! Param Ina Seli itu sakti. Baunya seperti kaus kaki kerbau, tapi sakti."],
      ["hero", "Ayahmu tidak keberatan kau ikut?"],
      ["lewa", "Oh, keberatan sekali. Dia bilang 'tidak' sebelas kali. Lalu Ina Seli bilang sesuatu padanya, pelan sekali, dan Ayah diam lama. Lalu dia bilang, 'Kalau aku tak bisa melarangmu, setidaknya jangan pergi sendirian.'"],
      ["lewa", "Jadi, ya, kau resmi jadi pengawalku. Selamat! Gajinya jagung titi."],
      ["narasi", "Lewa menerima tali penenang darimu. Ia mengelusnya pelan, dan untuk pertama kalinya, wajahnya yang ceria berubah serius."],
      ["lewa", "Ibu yang dulu mengajariku melempar tali. Katanya, tali yang dilempar dengan marah selalu meleset. Tali yang dilempar dengan sayang selalu sampai. Kemarin aku melemparnya dengan marah. Hari ini tidak."],
      ["lewa", "Bukit Sembrani ada di utara, di lingkaran batu tua. Arwah-arwah tugu berkeliaran di jalannya sejak tugu berhenti bernyanyi. Ikuti aku, aku tahu jalan pintas. Ayo, sebelum Ayah berubah pikiran!"],
    ],
    hadiah: { exp: 6200, gold: 280 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Sembrani Hill", tujuan: "Bring the calming rope to Lewa",
      teks: [
        "Look! Look! I can stand on tiptoe already! Ina Seli's salve is magic. It smells like buffalo socks, but it's magic.",
        "Your father doesn't mind you coming along?",
        "Oh, he minds a lot. He said 'no' eleven times. Then Ina Seli told him something, very quietly, and Father went silent for a long time. Then he said, 'If I can't stop you, at least don't go alone.'",
        "So, yes, you're officially my bodyguard. Congratulations! You'll be paid in popped corn.",
        "Lewa takes the calming rope from you. She strokes it gently, and for the first time, her cheerful face turns serious.",
        "Mother taught me to throw a rope. She said a rope thrown in anger always misses. A rope thrown with love always lands. Yesterday I threw it in anger. Not today.",
        "Sembrani Hill is to the north, in the old stone circle. Pillar spirits have roamed that path since the pillars stopped singing. Follow me, I know a shortcut. Come on, before Father changes his mind!",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 7, judul: "Bukit Sembrani", tipe: "pandu", npc: "lewa", area: "sabana",
    mulai: [57, 25],
    ajak: ["Ikuti aku! Kalau ketinggalan, salahmu sendiri, ya! ...Bercanda. Aku akan menunggu. Sedikit.", "Follow me! If you fall behind, that's your own fault! ...Kidding. I'll wait. A little."],
    titik: [
      { di: [44, 22], baris: [
        ["lewa", ["Lihat megalit ini. Ada ukiran kuda bersayap di sisinya, lihat? Leluhur kami memahatnya ratusan tahun lalu.", "Look at this megalith. There's a winged horse carved on its side, see? Our ancestors carved it hundreds of years ago."]],
        ["lewa", ["Waktu kecil, Ibu sering mengajakku ke sini. Dia bilang, kalau kita meraba ukiran ini sambil memejamkan mata, kita bisa mendengar kepak sayapnya.", "When I was little, Mother often brought me here. She said if you touch this carving with your eyes closed, you can hear its wings beating."]],
        ["hero", ["Dan kau mendengarnya?", "And did you hear it?"]],
        ["lewa", ["Tidak pernah. Tapi aku selalu pura-pura dengar, supaya Ibu senang. ...Ayo, lanjut. Aku tidak mau menangis di depan orang kota.", "Never. But I always pretended I did, to make Mother happy. ...Come on, let's keep going. I'm not crying in front of a city kid."]],
      ] },
      { di: [31, 17], sergap: { monster: "arwahTugu", jumlah: 3 }, baris: [
        ["lewa", ["Fiuh! Itu arwah tugu. Dulu mereka tinggal di dalam tugu dan ikut bernyanyi bersama angin.", "Phew! Those were pillar spirits. They used to live inside the pillars and sing along with the wind."]],
        ["lewa", ["Sejak tugunya diam, mereka seperti anak-anak yang diusir dari rumah. Bingung, lalu marah. Kasihan, sebenarnya.", "Since the pillars went quiet, they're like children thrown out of their home. Confused, then angry. Poor things, really."]],
      ] },
      { di: [30, 14], baris: [
        ["narasi", ["Di kaki bukit, rumput-rumput rebah ke satu arah, seperti dihempas angin yang sangat besar. Bulu-bulu hitam berserakan di mana-mana.", "At the foot of the hill, the grass lies flattened in one direction, as if struck by a tremendous wind. Black feathers are scattered everywhere."]],
        ["lewa", ["Di atas sana, di lingkaran batu. Itu sarangnya. Aku bisa merasakannya. Bulu kudukku berdiri semua.", "Up there, in the stone circle. That's its nest. I can feel it. Every hair on my neck is standing up."]],
        ["lewa", ["Tapi arwah-arwah itu berkumpul di lereng. Kita harus membersihkan jalan dulu.", "But those spirits are gathering on the slope. We have to clear the way first."]],
      ] },
    ],
    tujuan: "Ikuti Lewa menuju kaki Bukit Sembrani",
    teks: [
      ["narasi", "Dari kaki bukit, lingkaran batu megalit di puncak terlihat jelas: dua belas batu tegak mengelilingi tanah lapang yang hangus."],
      ["narasi", "Arwah-arwah tugu melayang di lereng, berputar pelan, berpendar kuning pucat seperti lentera yang kehabisan minyak."],
      ["lewa", "Aku akan menunggu di sini bersama Angin. Kalau kau sudah membersihkan lereng, aku menyusul. Dan... hati-hati. Aku tidak mau menjelaskan pada Ayah kenapa pengawalku hilang."],
    ],
    hadiah: { exp: 6500, gold: 320, potion: 2 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Sembrani Hill", tujuan: "Follow Lewa to the foot of Sembrani Hill",
      teks: [
        "From the foot of the hill, the megalith circle at the top is clearly visible: twelve standing stones surrounding a scorched clearing.",
        "Pillar spirits drift along the slope, circling slowly, glowing a pale yellow like lanterns running out of oil.",
        "I'll wait here with Wind. Once you've cleared the slope, I'll catch up. And... be careful. I don't want to explain to Father why my bodyguard went missing.",
      ] } },

  // ===== EP 8 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 8, judul: "Penjaga Bukit", tipe: "kill", target: "arwahTugu", need: 6,
    tujuan: "Kalahkan 6 Arwah Tugu di lereng Bukit Sembrani",
    teks: [
      ["narasi", "Arwah tugu terakhir memudar. Sebelum hilang, ia berbisik dengan suara seperti angin yang lewat di lubang batu: '...dia... menyuruh kami... diam...'"],
      ["narasi", "Lereng kini sepi. Lalu langit mendadak gelap. Sebuah bayangan raksasa melintas di atas kepalamu, dan rumput-rumput rebah ditiup kepak sayap yang tak bersuara."],
      ["lewa", "Itu dia. Itu Sembrani. Lihat benangnya... ya ampun, lebih banyak dari kemarin."],
      ["narasi", "Di puncak bukit, di tengah lingkaran batu, seekor kuda bersayap mendarat. Tubuhnya hitam legam, sayapnya terjerat ratusan benang yang menjulur ke langit, ke arah yang tak terlihat."],
      ["lewa", "Aku siap. Talinya siap. Kita tidak akan menyakitinya lebih dari perlu, ya? Janji?"],
    ],
    hadiah: { exp: 6800, gold: 320 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "Spirits of the Hill", tujuan: "Defeat 6 Pillar Spirits on the slopes of Sembrani Hill",
      teks: [
        "The last pillar spirit fades. Before it vanishes, it whispers in a voice like wind through holes in stone: '...he... told us... to be silent...'",
        "The slope falls quiet. Then the sky suddenly darkens. A giant shadow sweeps overhead, and the grass bends beneath the beat of soundless wings.",
        "There it is. That's Sembrani. Look at the threads... oh no, there are more than yesterday.",
        "At the top of the hill, in the middle of the stone circle, a winged horse lands. Its body is pitch black, its wings snared by hundreds of threads stretching up into the sky, toward somewhere unseen.",
        "I'm ready. The rope's ready. We won't hurt it more than we have to, right? Promise?",
      ] } },

  // ===== EP 9 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 9, judul: "Kuda Sembrani Hitam", tipe: "bos", monster: "kudaSembrani", bantuan: "lewa",
    serukan: [
      ["lewa", ["Sembrani! Ini aku, Lewa! Anak yang dulu menangis di kubur batu!", "Sembrani! It's me, Lewa! The girl who used to cry at the stone grave!"]],
      ["lewa", ["Incar benangnya, bukan kudanya!", "Aim for the threads, not the horse!"]],
      ["lewa", ["Sedikit lagi! Talinya hampir bisa kulempar!", "Almost there! I can nearly throw the rope!"]],
      ["lewa", ["Angin, maju! Jangan takut, dia bukan musuh!", "Go, Wind! Don't be scared, it's not our enemy!"]],
    ],
    tujuan: "Bebaskan Kuda Sembrani Hitam dari benang di Bukit Sembrani",
    teks: [
      ["narasi", "Kuda Sembrani terhuyung, sayapnya terkulai berat oleh jeratan benang. Lewa berlari maju dan melempar tali penenang. Tali itu melingkar sempurna di leher sang kuda."],
      ["lewa", "Kau bukan wayang. Kau penjaga. Ingat? Kau penjaga kami."],
      ["narasi", "Kuda itu berhenti meronta. Kau mengayunkan senjatamu, memutus benang-benang hitam satu per satu. Setiap benang yang putus berdesis seperti air disiram ke bara, lalu lenyap menjadi abu."],
      ["narasi", "Warna hitam di tubuhnya mengelupas seperti lumpur kering. Di baliknya, bulu putih berkilau muncul, dan sayapnya membentang keemasan, menangkap cahaya matahari sore."],
      ["kudaSembrani", "(Kuda Sembrani menundukkan kepala dan menyentuhkan moncongnya ke dahi Lewa, lama sekali, seperti seseorang yang mengenali wajah lama.)"],
      ["narasi", "Lalu ia meringkik panjang, ringkikan pertama yang terdengar di padang ini sejak empat puluh hari, dan melesat ke langit. Awan-awan berkumpul mengikuti kepak sayapnya."],
      ["narasi", "Setetes air jatuh di pipimu. Lalu setetes lagi. Gerimis turun di Bukit Sembrani."],
    ],
    hadiah: { exp: 18000, gold: 600, potion: 3 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The Black Sembrani", tujuan: "Free the Black Sembrani from its threads on Sembrani Hill",
      teks: [
        "The Sembrani staggers, its wings drooping heavy under the snare of threads. Lewa runs forward and throws the calming rope. It loops perfectly around the horse's neck.",
        "You're not a puppet. You're a guardian. Remember? You're our guardian.",
        "The horse stops thrashing. You swing your weapon, severing the black threads one by one. Each thread that snaps hisses like water poured on embers, then vanishes into ash.",
        "The black on its body peels away like dried mud. Beneath it, gleaming white fur appears, and its wings spread out golden, catching the afternoon sun.",
        "(The Sembrani bows its head and touches its muzzle to Lewa's forehead, for a long time, like someone recognizing an old face.)",
        "Then it lets out a long neigh, the first neigh heard on this plain in forty days, and soars into the sky. Clouds gather in the wake of its wings.",
        "A drop of water falls on your cheek. Then another. A drizzle falls on Sembrani Hill.",
      ] } },

  // ===== EP 10 =====
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 10, judul: "Gerimis Pertama", tipe: "bicara", npc: "lewa",
    tujuan: "Bicara dengan Lewa di bawah gerimis",
    teks: [
      ["lewa", "Hujan... Hujan! Lihat, kau lihat itu? Angin, kau lihat? Kau basah! Aku basah! Kita semua basah! Hahaha!"],
      ["narasi", "Lewa berputar-putar di bawah gerimis dengan tangan terentang, wajahnya menengadah ke langit. Kuda Angin meringkik dan menghentak-hentakkan kaki ikut gembira."],
      ["lewa", "Dia ingat aku. Kau lihat tadi? Dia menyentuh dahiku. Persis seperti waktu aku kecil, di kubur Ibu. Waktu itu aku menangis, dan dia datang, dan menyentuh dahiku begitu."],
      ["lewa", "Aku pikir itu cuma mimpi. Ayah bilang itu cuma mimpi. Ternyata bukan."],
      ["hero", "Mungkin Ibumu yang memintanya menjagamu."],
      ["lewa", "...Hei. Jangan bilang hal-hal begitu. Nanti aku menangis lagi, dan wajahku sudah basah kena hujan, jadi tidak ada yang bisa membedakan. Curang."],
      ["lewa", "Tapi ada yang aneh. Waktu benang-benang itu putus, sisanya tidak jatuh ke tanah. Benangnya ditarik, seperti digulung dari jauh. Ke arah timur laut. Ke Lembah Tugu."],
      ["lewa", "Dalang itu masih di sana, kan? Kalau kau mau ke sana, aku ikut! Jangan bilang tidak. Ayah sudah bilang tidak sebelas kali, jatahnya sudah habis untuk minggu ini. Ayo pulang, kita ceritakan pada Ina Seli!"],
    ],
    hadiah: { exp: 6800, gold: 350 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The First Drizzle", tujuan: "Talk to Lewa in the drizzle",
      teks: [
        "Rain... Rain! Look, do you see that? Wind, do you see? You're wet! I'm wet! We're all wet! Hahaha!",
        "Lewa spins in the drizzle with her arms spread wide, her face turned up to the sky. Wind neighs and stamps her hooves, joining in the joy.",
        "It remembered me. Did you see? It touched my forehead. Just like when I was little, at Mother's grave. I was crying, and it came, and touched my forehead just like that.",
        "I thought it was only a dream. Father said it was only a dream. It wasn't.",
        "Maybe your mother asked it to watch over you.",
        "...Hey. Don't say things like that. I'll cry again, and my face is already wet from the rain, so nobody could tell the difference. That's cheating.",
        "But something was strange. When the threads snapped, the remnants didn't fall to the ground. They were pulled away, like they were being reeled in from afar. To the northeast. To the Valley of Pillars.",
        "That Puppeteer's still there, isn't he? If you're going, I'm coming! Don't say no. Father's already said no eleven times, he's used up the week's supply. Let's go home and tell Ina Seli!",
      ] } },
  { bab: "Bab 13 · Padang Tanpa Hujan", ep: 10, judul: "Gerimis Pertama", tipe: "bicara", npc: "inaSeli", buka: "tugu",
    tujuan: "Kembali ke Kampung Megalit dan temui Ina Seli",
    teks: [
      ["inaSeli", "Kau dengar itu, Nak? Bukan, bukan hujannya. Di balik hujan. Dengarkan baik-baik."],
      ["narasi", "Kau memasang telinga. Jauh di utara, di balik suara gerimis di atap ilalang, terdengar senandung yang sangat samar. Lalu senandung itu putus di tengah, seperti lagu yang kehilangan baitnya."],
      ["inaSeli", "Tugu-tugu itu mencoba bernyanyi lagi. Sembrani sudah bebas, dan sebagian benang terlepas. Tapi lagunya patah. Ada nada yang hilang, dan nada itu dari Tugu Agung, tugu terbesar di ujung lembah."],
      ["inaSeli", "Tugu Agung menyimpan suara para leluhur kami. Suara paling tua di padang ini. Kalau dalang itu ingin membuat dunia sunyi, di situlah ia harus mulai. Membungkam suara yang paling tua dulu."],
      ["hero", "Namanya Ki Lirih, Ina. Dulu ia dalang istana di negeri yang jauh. Ia kehilangan keluarganya, dan suaranya, dan sekarang ia ingin semua orang kehilangan suara juga."],
      ["inaSeli", "...Ina sudah menduga ada kesedihan di balik topeng itu. Waktu ia menulis 'kain tanpa motif' di tanah, tangannya gemetar. Orang yang marah tangannya kuat. Orang yang sedih tangannya gemetar."],
      ["inaSeli", "Dan orang sedih, Nak, kadang bisa berbuat hal yang lebih menakutkan daripada orang marah. Karena orang marah ingin menang. Orang sedih hanya ingin rasa sakitnya berhenti, berapa pun harganya."],
      ["inaSeli", "Jalan setapak ke Lembah Tugu sudah Ina buka. Penjaga jalan itu cucu Ina, jadi tidak ada yang akan melarangmu. Bawa Lewa kalau dia memaksa. Dan dia pasti memaksa."],
    ],
    hadiah: { exp: 7000, gold: 400 },
    en: { bab: "Chapter 13 · The Rainless Plain", judul: "The First Drizzle", tujuan: "Return to Megalith Village and see Ina Seli",
      teks: [
        "Do you hear that, child? No, not the rain. Behind the rain. Listen closely.",
        "You strain your ears. Far to the north, behind the patter of drizzle on the thatched roofs, comes a very faint hum. Then the hum breaks off in the middle, like a song that has lost its verse.",
        "The pillars are trying to sing again. Sembrani is free, and some of the threads have come loose. But the song is broken. A note is missing, and that note comes from the Great Pillar, the largest one at the end of the valley.",
        "The Great Pillar holds the voices of our ancestors. The oldest voices on this plain. If that puppeteer wants to make the world silent, that's where he must begin. Silencing the oldest voices first.",
        "His name is Ki Lirih, Ina. He was once a court puppeteer in a faraway kingdom. He lost his family, and his voice, and now he wants everyone to lose their voices too.",
        "...I suspected there was sorrow behind that mask. When he wrote 'cloth without a pattern' in the dirt, his hand was shaking. An angry man's hand is strong. A grieving man's hand trembles.",
        "And a grieving man, child, can sometimes do things more frightening than an angry one. Because the angry want to win. The grieving only want the pain to stop, whatever the cost.",
        "I've opened the footpath to the Valley of Pillars. Its keeper is my grandson, so no one will stop you. Take Lewa if she insists. And she will insist.",
      ] } },
];

